n=int.from_bytes(x[4:8],"big");out=bytearray();p=8
while len(out)<n:
 flags=x[p];p+=1
 for bit in range(8):
  if len(out)>=n:break
  if flags&(1<<bit):
   distance=(x[p]<<8)|x[p+1];size=x[p+2]+4;p+=3
   if size==259:size+=(x[p]<<8)|x[p+1];p+=2
